import { useState, useEffect } from "react";
import axios from "axios";
import { motion } from "framer-motion";
import toast, { Toaster } from "react-hot-toast";
import { useDropzone } from "react-dropzone";
import { UploadCloud, Inbox, CheckCircle, Send } from "lucide-react";

const API = "http://127.0.0.1:8000";

export default function App() {
  const [user, setUser] = useState("");
  const [logged, setLogged] = useState(false);

  const [receiver, setReceiver] = useState("user2");
  const [file, setFile] = useState(null);

  const [msgs, setMsgs] = useState([]);
  const [pending, setPending] = useState([]);

  // 🔐 login
  const login = async () => {
    const f = new FormData();
    f.append("username", user);
    const res = await axios.post(API + "/login", f);

    if (res.data.ok) {
      setLogged(true);
      toast.success("Welcome 🚀");
    } else {
      toast.error("Invalid user");
    }
  };

  // 📁 drag-drop
  const { getRootProps, getInputProps } = useDropzone({
    onDrop: (files) => {
      if (files.length > 0) {
        setFile(files[0]);
        toast.success("File selected");
      }
    }
  });

  // 📤 send
  const send = async () => {
    if (!file) {
      toast.error("Select a file first");
      return;
    }

    const f = new FormData();
    f.append("sender", user);
    f.append("receiver", receiver);
    f.append("file", file);

    await axios.post(API + "/send", f);

    toast.success("Sent securely 🔐");
    load();
  };

  // 📥 load data
  const load = async () => {
    const inbox = await axios.get(API + "/inbox", { params: { user } });
    setMsgs(inbox.data);

    const pend = await axios.get(API + "/pending", { params: { user } });
    setPending(pend.data);
  };

  // ✅ approve
  const approve = async (id) => {
    try {
      await axios.post(API + "/approve", null, {
        params: { msg_id: id, user }
      });
      toast.success("Approved");
      load();
    } catch {
      toast.error("Cannot approve");
    }
  };

  // 🔓 read
  const read = async (id) => {
    const res = await axios.get(API + "/read", {
      params: { msg_id: id, user },
      responseType: "blob"
    });

    const cd = res.headers["content-disposition"];
    let filename = "file";

    if (cd) {
      const match = cd.match(/filename="(.+)"/);
      if (match) filename = match[1];
    }

    const url = URL.createObjectURL(new Blob([res.data]));
    const a = document.createElement("a");
    a.href = url;
    a.download = filename;
    a.click();

    toast.success("File downloaded 📥");
  };

  // 🔄 auto-refresh
  useEffect(() => {
    if (logged) {
      load();
      const i = setInterval(load, 3000);
      return () => clearInterval(i);
    }
  }, [logged]);

  // 🔐 login UI
  if (!logged) {
    return (
      <div style={center}>
        <Toaster />
        <motion.div style={glassCard} initial={{ scale: 0.9 }} animate={{ scale: 1 }}>
          <h2>🔐 SecureVault</h2>
          <input placeholder="user1 / user2..." onChange={e => setUser(e.target.value)} />
          <button onClick={login}>Login</button>
        </motion.div>
      </div>
    );
  }

  // 🎯 main UI
  return (
    <div style={app}>
      <Toaster />

      {/* Sidebar */}
      <div style={sidebar}>
        <h2>SecureVault</h2>
        <p>👤 {user}</p>
        <p><Inbox size={16}/> Inbox</p>
        <p><CheckCircle size={16}/> Approvals</p>
        <p><Send size={16}/> Send</p>
      </div>

      {/* Main */}
      <div style={main}>
        <h1>Secure Dashboard</h1>

        {/* Upload */}
        <motion.div {...getRootProps()} style={glassCard} whileHover={{ scale: 1.02 }}>
          <input {...getInputProps()} />
          <UploadCloud size={30}/>
          <p>Drag & Drop file</p>
        </motion.div>

        {/* fallback input */}
        <input type="file" onChange={(e)=>setFile(e.target.files[0])} />

        {/* Send */}
        <div style={glassCard}>
          <input placeholder="Receiver" onChange={e => setReceiver(e.target.value)} />
          <button onClick={send}>Send</button>
        </div>

        {/* Inbox */}
        <div style={glassCard}>
          <h3>Inbox</h3>
          {msgs.map(m => (
            <motion.div key={m.id} style={row} whileHover={{ scale: 1.02 }}>
              <span>{m.from}</span>
              <span style={badge(m.approved)}>
                {m.approved ? "Unlocked" : "Encrypted"}
              </span>
              {m.approved && <button onClick={() => read(m.id)}>Download</button>}
            </motion.div>
          ))}
        </div>

        {/* Approvals */}
        <div style={glassCard}>
          <h3>Approval Panel</h3>
          {pending.map(m => (
            <motion.div key={m.id} style={row} whileHover={{ scale: 1.02 }}>
              <span>Msg {m.id}</span>
              <button onClick={() => approve(m.id)}>Approve</button>
            </motion.div>
          ))}
        </div>

      </div>
    </div>
  );
}

/* 🎨 STYLES */

const app = {
  display: "flex",
  height: "100vh",
  background: "linear-gradient(135deg, #020617, #0f172a)",
  color: "white",
  fontFamily: "Segoe UI"
};

const sidebar = {
  width: 220,
  background: "rgba(0,0,0,0.6)",
  backdropFilter: "blur(10px)",
  padding: 20,
  borderRight: "1px solid #222"
};

const main = {
  flex: 1,
  padding: 30,
  overflow: "auto"
};

const glassCard = {
  background: "rgba(255,255,255,0.05)",
  backdropFilter: "blur(12px)",
  padding: 20,
  marginTop: 20,
  borderRadius: 12,
  border: "1px solid rgba(255,255,255,0.1)"
};

const row = {
  display: "flex",
  justifyContent: "space-between",
  marginTop: 10,
  padding: 10,
  borderRadius: 8,
  background: "rgba(0,0,0,0.3)"
};

const badge = (ok) => ({
  color: ok ? "#22c55e" : "#eab308",
  fontWeight: "bold"
});

const center = {
  display: "flex",
  justifyContent: "center",
  alignItems: "center",
  height: "100vh",
  background: "#020617"
};
